"""Apply reviewed question rubrics, retaining pre-edit cards for old history."""
import json
import re
from copy import deepcopy
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
path = ROOT / "content/questions.json"
cards = json.loads(path.read_text(encoding="utf-8"))
by_id = {card["id"]: card for card in cards}
archive_path = ROOT / "content/question-versions-v1.json"
archive = json.loads(archive_path.read_text(encoding="utf-8")) if archive_path.exists() else {}


def criterion(label, keywords, points):
    return {"label": label, "keywords": keywords, "max_points": points}


def update(identifier, question, followups, criteria):
    card = by_id[identifier]
    archive.setdefault(str(identifier), deepcopy(card))
    card.update(question=question, followups=followups, criteria=criteria)


