for card in cards:
    card.setdefault("followups", [])
    count = len(card["criteria"])
    for index, item in enumerate(card["criteria"]):
        item["id"] = f"c{index + 1}"
        item.setdefault("max_points", 100 // count + (index < 100 % count))
    assert sum(c["max_points"] for c in card["criteria"]) == 100

path.write_text(json.dumps(cards, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
archive_path.write_text(json.dumps(archive, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
for topic, filename in [("classical_ml", "classical-ml.md"), ("data_science", "data-science.md"), ("nlp", "nlp.md"), ("cv", "cv.md"), ("dl", "dl.md")]:
    selected = [c for c in cards if c["topic_id"] == topic]
    document = ROOT / "content" / filename
    document.write_text(re.sub(r"(?m)^(\d+)\. .+$", lambda match: f"{match[1]}. {selected[int(match[1])-1]['question']}", document.read_text(encoding="utf-8")), encoding="utf-8")
print(f"Updated rubrics: {len(cards)}; reviewed cards archived: {len(archive)}")
